import numpy as np
from pfapack import pfaffian

def calc(W,H,edges,signE=1,signN=1,tx=1,ty=1):
 A=np.zeros((4*W*H,4*W*H))
 L=np.array([[0,1,-1,1],[-1,0,1,-1],[1,-1,0,1],[-1,1,-1,0]],float)
 for v in range(W*H): A[4*v:4*v+4,4*v:4*v+4]=L
 for (x,y,d),t in edges.items():
  if d=='E':
   a=4*(y*W+x); b=4*(y*W+(x+1)%W)+2; val=signE*tx**(x==W-1)*t
  else:
   a=4*(y*W+x)+1; b=4*(((y+1)%H)*W+x)+3; val=signN*ty**(y==H-1)*t
  A[a,b]=val; A[b,a]=-val
 return pfaffian.pfaffian(A,method='H')
W=H=3
p={(0,0,'E'):.1,(1,0,'N'):.1,(0,1,'E'):.1,(0,0,'N'):.1}
for se in [1,-1]:
 for sn in [1,-1]:
