const r=await tools.exec_command({cmd:"python3 - <<'PY'
import numpy as np,itertools,math
from pfapack import pfaffian
W=H=3; rng=np.random.default_rng(13)
edges=[]
for y in range(H):
 for x in range(W):
  for d in 'EN': edges.append((x,y,d,float(rng.uniform(-.4,.5))))
L=np.array([[0,1,-1,1],[-1,0,1,-1],[1,-1,0,1],[-1,1,-1,0]])
def pf(tx,ty):
 A=np.zeros((4*W*H,4*W*H))
 for v in range(W*H): A[4*v:4*v+4,4*v:4*v+4]=L
 for x,y,d,t in edges:
  if d=='E': a=4*(y*W+x);b=4*(y*W+(x+1)%W)+2;z=tx if x==W-1 else 1
  else: a=4*(y*W+x)+1;b=4*(((y+1)%H)*W+x)+3;z=ty if y==H-1 else 1
  A[a,b]=z*t;A[b,a]=-z*t
 return pfaffian.pfaffian(A,method='H')
ps=[pf(1,1),pf(-1,1),pf(1,-1),pf(-1,-1)]
p_even=(ps[0]+ps[1]+ps[2]-ps[3])/2
true=0
for bits in itertools.product([-1,1],repeat=W*H):
 v=1
 for x,y,d,t in edges:
  a=y*W+x;b=y*W+(x+1)%W if d=='E' else ((y+1)%H)*W+x
  v*=1+t*bits[a]*bits[b]
 true+=v
true/=2**(W*H)
print(ps,'pf combo',p_even,'true',true,'err',p_even-true)
PY",workdir:"/root",yield_time_ms:10000});text(r.output);

